check('the separately compiled daemon leaves recurring work off by default and only queues it with the explicit scheduler flag',async f=>{
 let child:ReturnType<typeof spawn>|undefined,login:string|undefined,output='';
 const stop=async()=>{if(child&&child.exitCode===null){const ended=new Promise<number|null>(resolve=>child!.once('exit',resolve));child.kill('SIGTERM');assert.equal(await Promise.race([ended,delay(2000,undefined,{ref:false}).then(()=>-1)]),0);}child=undefined;};
 try{
  const manual=await f.request('reports/jobs',{reportId:'finance.trial-balance',parameters:{through:'2026-12-31'}},'staff');assert.equal(manual.response.status,202);login='kavosh_schedule_'+randomUUID().replaceAll('-','');const password='synthetic_only_'+randomUUID().replaceAll('-',''),db=(await f.pg.query<{name:string}>('SELECT current_database() name')).rows[0].name;assert.match(login,/^kavosh_schedule_[a-f0-9]{32}$/);assert.match(db,/^kavosh_test_[a-f0-9]{32}$/);await f.pg.exec(`CREATE ROLE ${login} LOGIN NOSUPERUSER NOBYPASSRLS PASSWORD '${password}';GRANT kavosh_automation_worker TO ${login}`);const url=new URL(process.env.TEST_DATABASE_URL!);url.username=login;url.password=password;url.pathname='/'+db;
  const launch=(scheduler:boolean)=>{const command=process.env.REPORT_WORKER_COMPILED_ENTRY?[process.env.REPORT_WORKER_COMPILED_ENTRY]:['--import','tsx','scripts/process-reports.ts'];child=spawn(process.execPath,command,{cwd:process.cwd(),env:{PATH:process.env.PATH,NODE_ENV:'test',DATABASE_SSL_MODE:'disable',REPORT_WORKER_ENABLED:'true',REPORT_WORKER_DATABASE_URL:url.toString(),REPORT_WORKER_ACADEMIES:JSON.stringify([f.a]),...(scheduler?{REPORT_SCHEDULER_ENABLED:'true'}:{})},stdio:['ignore','ignore','pipe']});child.stderr?.on('data',d=>output+=String(d).slice(0,2000));};
  const wait=async(sql:string,params:unknown[])=>{for(let n=0;n<120;n++){if((await f.pg.query(sql,params)).rows.length)return;if(child?.exitCode!==null)break;await delay(25);}assert.fail('Daemon did not complete: '+output);};
  launch(false);await wait("SELECT id FROM public.report_jobs WHERE id=$1 AND status='succeeded'",[manual.body.data.id]);assert.equal((await f.occurrences()).body.data.length,0);await stop();launch(true);await wait("SELECT j.id FROM public.report_jobs j JOIN public.report_schedule_occurrences o ON o.job_id=j.id WHERE o.schedule_id=$1 AND j.status='succeeded'",[f.id]);assert.equal((await f.occurrences()).body.data.length,1);await stop();assert.doesNotMatch(output,/postgresql:|synthetic_only_|password|token_hash/i);
 }finally{if(child&&child.exitCode===null){child.kill('SIGKILL');await new Promise(resolve=>child!.once('exit',resolve));}if(login)await f.pg.exec('DROP ROLE '+login);}
});
